import pytest


def _parse_log_line(line: str):
    if "parse_log_line" in globals():
        return globals()["parse_log_line"](line)

    for module_name in ("solution", "code", "main", "app"):
        try:
            module = __import__(module_name)
            return module.parse_log_line(line)
        except (ImportError, AttributeError):
            continue

    raise NameError("parse_log_line is not available")


@pytest.mark.parametrize(
    "line, expected",
    [
        (
            "2024-01-15 10:30:45 ERROR [auth] Login failed for user admin",
            {
                "date": "2024-01-15",
                "time": "10:30:45",
                "level": "ERROR",
                "module": "auth",
                "message": "Login failed for user admin",
            },
        ),
        (
            "2024-01-15 10:30:45 INFO [api] Request completed",
            {
                "date": "2024-01-15",
                "time": "10:30:45",
                "level": "INFO",
                "module": "api",
                "message": "Request completed",
            },
        ),
        (
            "2024-01-15 10:30:45 WARN [cache] Cache miss",
            {
                "date": "2024-01-15",
                "time": "10:30:45",
                "level": "WARN",
                "module": "cache",
                "message": "Cache miss",
            },
        ),
        (
            "2024-01-15 10:30:45 DEBUG [db] Query executed",
            {
                "date": "2024-01-15",
                "time": "10:30:45",
                "level": "DEBUG",
                "module": "db",
                "message": "Query executed",
            },
        ),
    ],
)
def test_happy_path_valid_log_line(line, expected):
    assert _parse_log_line(line) == expected


@pytest.mark.parametrize(
    "line",
    [
        "",
        "   ",
        "2024",
        "2024-01-15",
        "2024-01-15 10:30:45",
        "2024-01-15 10:30:45 ERROR",
        "2024-01-15 10:30:45 ERROR [auth]",
        "2024-01-15 10:30:45 ERROR [auth] ",
        "2024-01-15  10:30:45 ERROR [auth] message",
        "2024-01-15 10:30:45  ERROR [auth] message",
    ],
)
def test_edge_cases_return_none(line):
    assert _parse_log_line(line) is None


@pytest.mark.parametrize(
    "level",
    [
        "CRITICAL",
        "info",
        "warning",
        "ERR",
        "ERRORX",
        "ERROR1",
        "",
    ],
)
def test_invalid_log_level_returns_none(level):
    line = f"2024-01-15 10:30:45 {level} [auth] message"
    assert _parse_log_line(line) is None


@pytest.mark.parametrize(
    "module_raw, expected_module",
    [
        ("[auth]", "auth"),
        ("[database]", "database"),
        ("[module-with-dash]", "module-with-dash"),
        ("[module_underscore]", "module_underscore"),
        ("[[nested]]", "nested"),
        ("[]", ""),
        ("[auth", "auth"),
        ("auth]", "auth"),
        ("auth", "auth"),
    ],
)
def test_module_name_extraction(module_raw, expected_module):
    line = f"2024-01-15 10:30:45 INFO {module_raw} message"
    result = _parse_log_line(line)

    assert result is not None
    assert result["module"] == expected_module


@pytest.mark.parametrize(
    "message",
    [
        "Login  failed",
        "Multiple   spaces   here",
        "Trailing spaces   ",
        "  Leading spaces",
        "a  b  c",
    ],
)
def test_multiple_spaces_in_message_are_preserved(message):
    line = f"2024-01-15 10:30:45 ERROR [auth] {message}"
    result = _parse_log_line(line)

    assert result is not None
    assert result["message"] == message

