#!/usr/bin/env python3
"""
CLI tool to summarize log levels in .log files.

Usage:
    python log_summary.py /path/to/logs --min-errors 3
"""

import argparse
import re
import sys
from pathlib import Path

LOG_LEVELS = ("INFO", "WARN", "ERROR", "DEBUG")
LEVEL_PATTERNS = {level: re.compile(rf"\b{level}\b") for level in LOG_LEVELS}


def parse_args(argv=None):
    parser = argparse.ArgumentParser(
        description="Count INFO, WARN, ERROR, and DEBUG occurrences per .log file."
    )
    parser.add_argument(
        "directory",
        help="Directory containing .log files"
    )
    parser.add_argument(
        "--min-errors",
        type=int,
        default=0,
        metavar="N",
        help="Only show files with at least N ERROR entries (default: 0)"
    )

    args = parser.parse_args(argv)

    if args.min_errors < 0:
        parser.error("--min-errors must be greater than or equal to 0")

    return args


def count_levels(path: Path) -> dict:
    """Count occurrences of each log level in a single file."""
    counts = {level: 0 for level in LOG_LEVELS}

    with path.open("r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            for level, pattern in LEVEL_PATTERNS.items():
                counts[level] += len(pattern.findall(line))

    return counts


def format_table(rows: list) -> str:
    """Format summary rows as an aligned text table."""
    headers = ["file", "INFO", "WARN", "ERROR", "DEBUG"]

    table = [headers]
    for row in rows:
        table.append([
            row["file"],
            str(row["INFO"]),
            str(row["WARN"]),
            str(row["ERROR"]),
            str(row["DEBUG"]),
        ])

    widths = [
        max(len(row[i]) for row in table)
        for i in range(len(headers))
    ]

    lines = []
    for idx, row in enumerate(table):
        lines.append(
            " | ".join(cell.ljust(widths[i]) for i, cell in enumerate(row)).rstrip()
        )
        if idx == 0:
            lines.append("-+-".join("-" * width for width in widths))

    return "\n".join(lines)


def main(argv=None) -> int:
    args = parse_args(argv)

    directory = Path(args.directory)

    if not directory.is_dir():
        print(f"error: {directory} is not a directory", file=sys.stderr)
        return 1

    log_files = sorted(path for path in directory.glob("*.log") if path.is_file())

    if not log_files:
        print("No .log files found.")
        return 0

    rows = []

    for path in log_files:
        try:
            counts = count_levels(path)
        except OSError as exc:
            print(f"warning: could not read {path}: {exc}", file=sys.stderr)
            continue

        if counts["ERROR"] >= args.min_errors:
            rows.append({
                "file": path.name,
                **counts,
            })

    if not rows:
        print(f"No files with at least {args.min_errors} ERROR entries.")
        return 0

    print(format_table(rows))
    return 0


if __name__ == "__main__":
    sys.exit(main())
